import json
from typing import Literal
from langchain_core.messages import AIMessage, ToolMessage, HumanMessage
from langgraph.graph import StateGraph, START, END

from sky.agents.state import SkyAgentState
from sky.agents.executor import executor_node
from sky.agents.toolbuilder import toolbuilder_node, register_tool_node
from sky.tools.registry import registry

def tool_execution_node(state: SkyAgentState) -> dict:
    """Executes standard tool calls generated by Executor."""
    messages = state["messages"]
    last_message = messages[-1]
    
    if not isinstance(last_message, AIMessage) or not last_message.tool_calls:
        return {}

    # Map tool names to tool instances
    tools_map = {t.name: t for t in registry.get_all_tools()}
    tool_messages = []

    for tc in last_message.tool_calls:
        name = tc["name"]
        args = tc.get("args", {})
        call_id = tc["id"]

        if name == "request_toolbuilder_build_tool":
            # Handled separately by toolbuilder flow
            continue

        tool_instance = tools_map.get(name)
        if tool_instance:
            try:
                result = tool_instance.invoke(args)
            except Exception as e:
                result = f"Error running tool '{name}': {str(e)}"
        else:
            result = f"Error: Tool '{name}' is not registered."

        tool_messages.append(
            ToolMessage(
                tool_call_id=call_id,
                name=name,
                content=str(result)
            )
        )

    return {"messages": tool_messages}

def route_executor(state: SkyAgentState) -> Literal["toolbuilder", "tool_execution", "__end__"]:
    """Determines next node after executor runs."""
    if state.get("missing_tool_request"):
        return "toolbuilder"
    
    last_message = state["messages"][-1]
    if isinstance(last_message, AIMessage) and last_message.tool_calls:
        # Check if any call is for request_toolbuilder_build_tool
        for tc in last_message.tool_calls:
            if tc["name"] == "request_toolbuilder_build_tool":
                return "toolbuilder"
        return "tool_execution"
        
    return "__end__"

def register_tool_wrapper_node(state: SkyAgentState) -> dict:
    """Invokes registration and ensures tool_call_id is properly satisfied."""
    request = state.get("missing_tool_request") or {}
    tool_call_id = request.get("tool_call_id")
    tool_name = request.get("tool_name", "custom_tool")

    reg_result = register_tool_node(state)
    
    # If this was initiated by a tool call from executor, append matching ToolMessage
    if tool_call_id:
        error = reg_result.get("last_build_error")
        if error:
            resp_content = f"Failed to build tool '{tool_name}': {error}"
        else:
            resp_content = f"Tool '{tool_name}' successfully built and registered. It is now ready for use!"
        
        tool_msg = ToolMessage(
            tool_call_id=tool_call_id,
            name="request_toolbuilder_build_tool",
            content=resp_content
        )
        existing_msgs = reg_result.get("messages", [])
        reg_result["messages"] = [tool_msg] + existing_msgs

    return reg_result

def route_tool_registration(state: SkyAgentState) -> Literal["toolbuilder", "executor"]:
    """If build failed and attempts < 3, retry toolbuilder; else go back to executor."""
    last_error = state.get("last_build_error")
    attempts = state.get("tool_build_attempts", 0)
    if last_error and attempts < 3:
        return "toolbuilder"
    return "executor"

def build_sky_graph():
    """Constructs the LangGraph coordinating Executor and Toolbuilder."""
    builder = StateGraph(SkyAgentState)

    # Add Nodes
    builder.add_node("executor", executor_node)
    builder.add_node("tool_execution", tool_execution_node)
    builder.add_node("toolbuilder", toolbuilder_node)
    builder.add_node("register_tool", register_tool_wrapper_node)

    # Add Edges
    builder.add_edge(START, "executor")
    
    builder.add_conditional_edges(
        "executor",
        route_executor,
        {
            "toolbuilder": "toolbuilder",
            "tool_execution": "tool_execution",
            "__end__": END,
        }
    )
    
    builder.add_edge("tool_execution", "executor")
    builder.add_edge("toolbuilder", "register_tool")
    
    builder.add_conditional_edges(
        "register_tool",
        route_tool_registration,
        {
            "toolbuilder": "toolbuilder",
            "executor": "executor",
        }
    )

    return builder.compile()

# Pre-compiled graph singleton
sky_graph = build_sky_graph()
